import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "@/components/ui/chart";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { trpc } from "@/lib/trpc";
import { getPerformanceInterpretation } from "@/lib/performanceInterpretation";
import { isValidAnalyticsDateRange, resolveAnalyticsDateRange, toggleCampaignComparison, type DatePreset } from "@/lib/analyticsFilters";
import { csvMappingPresets, parseAnalyticsCsv, type CsvMappingPreset } from "@/lib/analyticsCsv";
import { toast } from "sonner";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts";
import { Activity, AlertTriangle, ArrowUpRight, BarChart3, Bookmark, BrainCircuit, CalendarRange, ChartNoAxesCombined, CircleDollarSign, Eye, FileUp, GitCompareArrows, Layers3, MousePointerClick, Pencil, Pin, Plus, RefreshCw, Save, Sparkles, Target, Trash2, TrendingUp, Video, X } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

type Platform = "meta" | "tiktok" | "youtube";

const platformNames: Record<Platform, string> = { meta: "Meta", tiktok: "TikTok", youtube: "YouTube" };
const platformTone: Record<Platform, string> = { meta: "#8b9cff", tiktok: "#ef80aa", youtube: "#f0bf6b" };
const trendConfig = { impressions: { label: "Impressions", color: "#f5c8da" }, engagements: { label: "Engagements", color: "#a58cff" } } satisfies ChartConfig;
const platformConfig = { impressions: { label: "Impressions", color: "#f5c8da" } } satisfies ChartConfig;
const formatNumber = (value: number) => new Intl.NumberFormat("en-US", { notation: value >= 10000 ? "compact" : "standard", maximumFractionDigits: 1 }).format(value);
const formatMoney = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 2 }).format(value);
const today = new Date().toISOString().slice(0, 10);
const datePresetLabels: Record<DatePreset, string> = { all: "All time", last7: "Last 7 days", last30: "Last 30 days", custom: "Custom range" };

export default function Analytics() {
  const utils = trpc.useUtils();
  const campaigns = trpc.campaign.list.useQuery();
  const [datePreset, setDatePreset] = useState<DatePreset>("all");
  const [customStartDate, setCustomStartDate] = useState("");
  const [customEndDate, setCustomEndDate] = useState("");
  const [selectedCampaignIds, setSelectedCampaignIds] = useState<number[]>([]);
  const activeRange = datePreset === "custom" ? { startDate: customStartDate || undefined, endDate: customEndDate || undefined } : resolveAnalyticsDateRange(datePreset);
  const overviewInput = useMemo(() => ({ ...activeRange, campaignIds: selectedCampaignIds.length ? selectedCampaignIds : undefined }), [activeRange.startDate, activeRange.endDate, selectedCampaignIds]);
  const invalidDateRange = datePreset === "custom" && !isValidAnalyticsDateRange(customStartDate, customEndDate);
  const overview = trpc.analytics.overview.useQuery(overviewInput, { enabled: !invalidDateRange });
  const savedViews = trpc.analytics.views.list.useQuery();
  const record = trpc.analytics.record.useMutation({ onSuccess: () => { void utils.analytics.overview.invalidate(); toast.success("Analytics snapshot saved."); } });
  const saveView = trpc.analytics.views.create.useMutation({ onSuccess: () => { void utils.analytics.views.list.invalidate(); toast.success("Comparison view saved."); } });
  const deleteView = trpc.analytics.views.delete.useMutation({ onSuccess: () => { void utils.analytics.views.list.invalidate(); toast.success("Saved view removed."); } });
  const renameView = trpc.analytics.views.rename.useMutation({ onSuccess: () => { void utils.analytics.views.list.invalidate(); toast.success("Saved view renamed."); } });
  const setDefaultView = trpc.analytics.views.setDefault.useMutation({ onSuccess: () => { void utils.analytics.views.list.invalidate(); toast.success("Default analytics view updated."); } });
  const importSnapshots = trpc.analytics.importSnapshots.useMutation({ onSuccess: result => { void utils.analytics.overview.invalidate(); toast.success(`${result.imported} verified snapshot${result.imported === 1 ? "" : "s"} imported.`); } });
  const [showForm, setShowForm] = useState(false);
  const [showSaveDialog, setShowSaveDialog] = useState(false);
  const [showCsvDialog, setShowCsvDialog] = useState(false);
  const [csvText, setCsvText] = useState("");
  const [csvFallbackCampaignId, setCsvFallbackCampaignId] = useState("");
  const [csvMappingPreset, setCsvMappingPreset] = useState<CsvMappingPreset>("auto");
  const [viewName, setViewName] = useState("");
  const [editingView, setEditingView] = useState<any | null>(null);
  const [renameDraft, setRenameDraft] = useState("");
  const didApplyDefault = useRef(false);
  const [entry, setEntry] = useState({ campaignId: "", platform: "meta" as Platform, metricDate: today, impressions: "", engagements: "", clicks: "", conversions: "", videoViews: "", saves: "", spend: "" });
  const data = overview.data;
  const hasData = Boolean(data?.snapshotCount);
  const platformChartData = useMemo(() => data?.platforms.map(item => ({ name: platformNames[item.platform as Platform], impressions: item.impressions, fill: platformTone[item.platform as Platform] })) || [], [data]);
  const rangeLabel = datePreset === "custom" ? (customStartDate || customEndDate ? `${customStartDate || "Beginning"} → ${customEndDate || "Present"}` : "Custom range") : datePresetLabels[datePreset];
  const csvPreview = useMemo(() => csvText ? parseAnalyticsCsv(csvText, campaigns.data || [], csvFallbackCampaignId ? Number(csvFallbackCampaignId) : undefined, csvMappingPreset) : null, [csvText, campaigns.data, csvFallbackCampaignId, csvMappingPreset]);

  const setField = (field: keyof typeof entry, value: string) => setEntry(current => ({ ...current, [field]: value }));
  const selectPreset = (preset: DatePreset) => setDatePreset(preset);
  const setCustomDate = (field: "start" | "end", value: string) => { setDatePreset("custom"); field === "start" ? setCustomStartDate(value) : setCustomEndDate(value); };
  const resetFilters = () => { setDatePreset("all"); setCustomStartDate(""); setCustomEndDate(""); setSelectedCampaignIds([]); };
  const saveCurrentView = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!viewName.trim()) { toast.error("Name this comparison view before saving it."); return; }
    if (invalidDateRange) { toast.error("Correct the custom date range before saving this view."); return; }
    try {
      await saveView.mutateAsync({
        name: viewName.trim(),
        datePreset,
        startDate: datePreset === "custom" ? customStartDate || undefined : undefined,
        endDate: datePreset === "custom" ? customEndDate || undefined : undefined,
        campaignIds: selectedCampaignIds,
      });
      setShowSaveDialog(false); setViewName("");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Comparison view could not be saved."); }
  };
  const applySavedView = (view: any) => {
    const availableCampaignIds = new Set((campaigns.data || []).map(campaign => campaign.id));
    const campaignIds = (view.campaignIds as number[]).filter(id => availableCampaignIds.has(id));
    setDatePreset(view.datePreset as DatePreset);
    setCustomStartDate(view.startDate || ""); setCustomEndDate(view.endDate || ""); setSelectedCampaignIds(campaignIds);
    if (campaignIds.length !== view.campaignIds.length) toast.message("A campaign from this saved view is no longer available, so the remaining filters were applied.");
    else toast.success(`Applied “${view.name}”.`);
  };
  useEffect(() => {
    const defaultView = savedViews.data?.find(view => view.isDefault === 1);
    if (defaultView && !didApplyDefault.current) { didApplyDefault.current = true; applySavedView(defaultView); }
  }, [savedViews.data]);
  const removeSavedView = async (viewId: number) => {
    try { await deleteView.mutateAsync({ id: viewId }); } catch (error) { toast.error(error instanceof Error ? error.message : "Saved view could not be removed."); }
  };
  const renameSavedView = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!editingView || !renameDraft.trim()) { toast.error("Enter a name for this comparison view."); return; }
    try { await renameView.mutateAsync({ id: editingView.id, name: renameDraft.trim() }); setEditingView(null); setRenameDraft(""); } catch (error) { toast.error(error instanceof Error ? error.message : "Saved view could not be renamed."); }
  };
  const makeDefaultView = async (viewId: number) => {
    try { await setDefaultView.mutateAsync({ id: viewId }); } catch (error) { toast.error(error instanceof Error ? error.message : "Default view could not be updated."); }
  };
  const importCsv = async () => {
    if (!csvPreview?.rows.length) { toast.error("Choose a CSV with at least one valid reporting row."); return; }
    if (csvPreview.errors.length) { toast.error("Correct every reported CSV issue before importing verified snapshots."); return; }
    try { await importSnapshots.mutateAsync({ snapshots: csvPreview.rows }); setShowCsvDialog(false); setCsvText(""); setCsvFallbackCampaignId(""); setCsvMappingPreset("auto"); } catch (error) { toast.error(error instanceof Error ? error.message : "CSV import could not be completed."); }
  };
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!entry.campaignId) { toast.error("Select the campaign these metrics belong to."); return; }
    try {
      await record.mutateAsync({
        campaignId: Number(entry.campaignId), platform: entry.platform, metricDate: entry.metricDate,
        impressions: Number(entry.impressions || 0), engagements: Number(entry.engagements || 0), clicks: Number(entry.clicks || 0), conversions: Number(entry.conversions || 0), videoViews: Number(entry.videoViews || 0), saves: Number(entry.saves || 0), spendCents: Math.round(Number(entry.spend || 0) * 100),
      });
      setShowForm(false); setEntry({ campaignId: "", platform: "meta", metricDate: today, impressions: "", engagements: "", clicks: "", conversions: "", videoViews: "", saves: "", spend: "" });
    } catch (error) { toast.error(error instanceof Error ? error.message : "Analytics snapshot could not be saved."); }
  };

  return <div className="min-h-screen text-white pulse-grid"><header className="flex flex-col gap-5 border-b border-white/[.07] px-6 py-5 sm:flex-row sm:items-center sm:justify-between sm:px-9"><div><p className="text-[10px] font-bold uppercase tracking-[.24em] text-rose-200/70">Post-launch intelligence</p><h1 className="mt-1 font-display text-3xl tracking-tight">Performance command</h1></div><Button onClick={() => setShowForm(value => !value)} className="h-10 bg-rose-200 text-[#281b2d] hover:bg-rose-100"><Plus className="mr-2 h-4 w-4" />Add verified metrics</Button></header><main className="mx-auto w-full max-w-[1480px] px-5 py-8 sm:px-8 lg:px-10">
    <section className="mb-8 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-rose-200">Campaign analytics</p><h2 className="mt-3 max-w-3xl font-display text-4xl leading-[1.04] tracking-[-.03em] sm:text-5xl">See the signals behind the creative.</h2><p className="mt-5 max-w-2xl text-[15px] leading-7 text-white/55">Track first-party platform snapshots against the campaigns you have actually launched. Every chart and rate is calculated from the metrics you record here.</p></div><div className="rounded-[26px] border border-rose-200/15 bg-gradient-to-br from-rose-300/15 via-violet-400/10 to-transparent p-6"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.16em] text-rose-100/75">Data provenance</p><Sparkles className="h-5 w-5 text-rose-200" /></div><p className="mt-5 font-display text-2xl leading-tight">No fabricated performance data. Only the verified snapshots you add are visualized.</p><p className="mt-3 text-xs leading-5 text-white/50">Use daily or weekly exports from Meta, TikTok, and YouTube to maintain a current, comparable view.</p></div></section>
    <AnalyticsControls datePreset={datePreset} customStartDate={customStartDate} customEndDate={customEndDate} selectedCampaignIds={selectedCampaignIds} campaigns={campaigns.data || []} rangeLabel={rangeLabel} invalidDateRange={invalidDateRange} onPreset={selectPreset} onCustomDate={setCustomDate} onToggleCampaign={campaignId => setSelectedCampaignIds(current => toggleCampaignComparison(current, campaignId))} onReset={resetFilters} onSave={() => setShowSaveDialog(true)} />
    <SavedViewsEnhanced views={savedViews.data || []} campaigns={campaigns.data || []} isError={savedViews.isError} onRetry={() => void savedViews.refetch()} onApply={applySavedView} onDelete={removeSavedView} onRename={(view: any) => { setEditingView(view); setRenameDraft(view.name); }} onSetDefault={makeDefaultView} onImport={() => setShowCsvDialog(true)} deletingId={deleteView.isPending ? deleteView.variables?.id : undefined} defaultingId={setDefaultView.isPending ? setDefaultView.variables?.id : undefined} />
    <Dialog open={showSaveDialog} onOpenChange={setShowSaveDialog}><DialogContent className="border-white/10 bg-[#191621] text-white sm:max-w-md"><form onSubmit={saveCurrentView}><DialogHeader><DialogTitle className="font-display text-3xl">Save this analysis</DialogTitle><DialogDescription className="leading-6 text-white/50">Store the active date window and selected campaigns. Future clicks apply the saved filters without resetting your workspace.</DialogDescription></DialogHeader><div className="mt-5"><Label htmlFor="view-name" className="text-xs text-white/65">Comparison view name</Label><Input id="view-name" autoFocus value={viewName} onChange={event => setViewName(event.target.value)} placeholder="e.g. Q3 creative comparison" className="mt-2 border-white/10 bg-white/[.04] text-white placeholder:text-white/25" /></div><div className="mt-4 rounded-2xl border border-white/[.08] bg-white/[.025] p-4 text-xs leading-5 text-white/52"><p className="font-semibold text-white/75">This view will remember</p><p className="mt-1">{rangeLabel} · {selectedCampaignIds.length ? `${selectedCampaignIds.length} selected campaign${selectedCampaignIds.length > 1 ? "s" : ""}` : "all campaigns"}</p></div><DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={() => setShowSaveDialog(false)} className="border-white/10 bg-transparent text-white hover:bg-white/[.08] hover:text-white">Cancel</Button><Button type="submit" disabled={saveView.isPending} className="bg-rose-200 text-[#281b2d] hover:bg-rose-100">{saveView.isPending ? "Saving…" : <><Save className="mr-2 h-4 w-4" />Save view</>}</Button></DialogFooter></form></DialogContent></Dialog>
    <RenameViewDialog view={editingView} name={renameDraft} isSaving={renameView.isPending} onName={setRenameDraft} onClose={() => setEditingView(null)} onSubmit={renameSavedView} />
    <CsvImportDialogEnhanced open={showCsvDialog} campaigns={campaigns.data || []} fallbackCampaignId={csvFallbackCampaignId} mappingPreset={csvMappingPreset} preview={csvPreview} isImporting={importSnapshots.isPending} onFallback={setCsvFallbackCampaignId} onPreset={setCsvMappingPreset} onFile={async (file: File) => setCsvText(await file.text())} onClose={() => { setShowCsvDialog(false); setCsvText(""); setCsvFallbackCampaignId(""); setCsvMappingPreset("auto"); }} onImport={importCsv} />
    {showForm && <form onSubmit={submit} className="mb-7 rounded-[26px] border border-rose-200/20 bg-[#171521]/95 p-6 shadow-2xl shadow-black/10"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-sm font-semibold">Record a verified analytics snapshot</p><p className="mt-1 text-xs text-white/45">Enter metrics from the platform reporting source. Spend is in USD.</p></div><Button type="submit" disabled={record.isPending} className="bg-white text-[#211a2a] hover:bg-rose-50">{record.isPending ? "Saving…" : "Save snapshot"}</Button></div><div className="mt-6 grid gap-4 md:grid-cols-3 lg:grid-cols-5"><Field label="Campaign"><select required value={entry.campaignId} onChange={event => setField("campaignId", event.target.value)} className="mt-2 h-10 w-full rounded-md border border-white/10 bg-[#201d2b] px-3 text-xs text-white outline-none focus:ring-2 focus:ring-rose-200/60"><option value="">Select campaign</option>{campaigns.data?.map(campaign => <option key={campaign.id} value={campaign.id}>{campaign.campaignName || campaign.productName}</option>)}</select></Field><Field label="Platform"><select value={entry.platform} onChange={event => setField("platform", event.target.value)} className="mt-2 h-10 w-full rounded-md border border-white/10 bg-[#201d2b] px-3 text-xs text-white outline-none focus:ring-2 focus:ring-rose-200/60">{(["meta", "tiktok", "youtube"] as Platform[]).map(platform => <option key={platform} value={platform}>{platformNames[platform]}</option>)}</select></Field><Field label="Snapshot date"><Input type="date" value={entry.metricDate} onChange={event => setField("metricDate", event.target.value)} className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Impressions"><Input inputMode="numeric" value={entry.impressions} onChange={event => setField("impressions", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Engagements"><Input inputMode="numeric" value={entry.engagements} onChange={event => setField("engagements", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Clicks"><Input inputMode="numeric" value={entry.clicks} onChange={event => setField("clicks", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Conversions"><Input inputMode="numeric" value={entry.conversions} onChange={event => setField("conversions", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Video views"><Input inputMode="numeric" value={entry.videoViews} onChange={event => setField("videoViews", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Saves"><Input inputMode="numeric" value={entry.saves} onChange={event => setField("saves", event.target.value)} placeholder="0" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="Spend (USD)"><Input inputMode="decimal" value={entry.spend} onChange={event => setField("spend", event.target.value)} placeholder="0.00" className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field></div></form>}
    {invalidDateRange ? <InvalidDateRangeState /> : overview.isLoading || campaigns.isLoading ? <div className="grid min-h-[440px] place-items-center"><Activity className="h-6 w-6 animate-pulse text-rose-200" /></div> : overview.isError || campaigns.isError ? <AnalyticsError onRetry={() => { void overview.refetch(); void campaigns.refetch(); }} /> : !hasData ? <EmptyAnalytics onAdd={() => setShowForm(true)} hasCampaigns={Boolean(campaigns.data?.length)} /> : <AnalyticsView data={data} platformChartData={platformChartData} comparisonIds={selectedCampaignIds} rangeLabel={rangeLabel} />}
  </main></div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <div><Label className="text-xs text-white/60">{label}</Label>{children}</div>; }

function AnalyticsControls({ datePreset, customStartDate, customEndDate, selectedCampaignIds, campaigns, rangeLabel, invalidDateRange, onPreset, onCustomDate, onToggleCampaign, onReset, onSave }: { datePreset: DatePreset; customStartDate: string; customEndDate: string; selectedCampaignIds: number[]; campaigns: any[]; rangeLabel: string; invalidDateRange: boolean; onPreset: (preset: DatePreset) => void; onCustomDate: (field: "start" | "end", value: string) => void; onToggleCampaign: (campaignId: number) => void; onReset: () => void; onSave: () => void }) { const isFiltered = datePreset !== "all" || selectedCampaignIds.length > 0; return <section className="mb-4 rounded-[26px] border border-white/[.09] bg-[#171521]/88 p-5 shadow-2xl shadow-black/10"><div className="flex flex-col gap-5 xl:flex-row xl:items-start xl:justify-between"><div><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-rose-200/10 text-rose-200"><CalendarRange className="h-4 w-4" /></span><div><p className="text-sm font-semibold">Analysis window</p><p className="mt-1 text-xs text-white/42">{rangeLabel} · {selectedCampaignIds.length ? `${selectedCampaignIds.length} campaign${selectedCampaignIds.length > 1 ? "s" : ""} in focus` : "All campaigns"}</p></div></div><div className="mt-4 flex flex-wrap gap-2">{(["all", "last7", "last30", "custom"] as DatePreset[]).map(preset => <button type="button" key={preset} onClick={() => onPreset(preset)} className={`rounded-full border px-3 py-1.5 text-xs font-semibold transition ${datePreset === preset ? "border-rose-200/50 bg-rose-200/15 text-white" : "border-white/10 bg-white/[.02] text-white/45 hover:bg-white/[.07] hover:text-white"}`}>{datePresetLabels[preset]}</button>)}</div>{datePreset === "custom" && <div className="mt-4 flex flex-wrap gap-3"><Field label="From"><Input type="date" value={customStartDate} onChange={event => onCustomDate("start", event.target.value)} className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field><Field label="To"><Input type="date" value={customEndDate} onChange={event => onCustomDate("end", event.target.value)} className="mt-2 border-white/10 bg-white/[.04] text-white" /></Field>{invalidDateRange && <p className="self-end pb-2 text-xs font-semibold text-amber-100">Choose an end date on or after the start date.</p>}</div>}</div><div className="min-w-0 xl:max-w-[560px]"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2"><GitCompareArrows className="h-4 w-4 text-violet-200" /><p className="text-sm font-semibold">Compare campaigns</p></div><div className="flex items-center gap-3">{isFiltered && <button type="button" onClick={onReset} className="inline-flex items-center gap-1 text-xs font-semibold text-rose-200 hover:text-rose-100"><X className="h-3.5 w-3.5" />Reset</button>}<button type="button" onClick={onSave} className="inline-flex items-center gap-1.5 rounded-lg border border-white/10 bg-white/[.03] px-2.5 py-1.5 text-xs font-semibold text-white/75 hover:bg-white/[.09] hover:text-white"><Bookmark className="h-3.5 w-3.5 text-rose-200" />Save view</button></div></div><p className="mt-1 text-xs leading-5 text-white/42">Choose up to two campaigns. Every metric, chart, and cue is recalculated using the selection.</p><div className="mt-3 flex flex-wrap gap-2">{campaigns.map(campaign => { const active = selectedCampaignIds.includes(campaign.id); return <button type="button" key={campaign.id} onClick={() => onToggleCampaign(campaign.id)} className={`max-w-[180px] truncate rounded-xl border px-3 py-2 text-xs font-semibold transition ${active ? "border-violet-300/50 bg-violet-300/12 text-white" : "border-white/10 bg-white/[.02] text-white/50 hover:bg-white/[.07] hover:text-white"}`}>{active && <span className="mr-1 text-violet-200">{selectedCampaignIds.indexOf(campaign.id) + 1}.</span>}{campaign.campaignName || campaign.productName}</button>; })}{!campaigns.length && <p className="text-xs text-white/35">Generate a campaign to enable comparison.</p>}</div></div></div></section>; }
function SavedViewsEnhanced({ views, campaigns, isError, onRetry, onApply, onDelete, onRename, onSetDefault, onImport, deletingId, defaultingId }: { views: any[]; campaigns: any[]; isError: boolean; onRetry: () => void; onApply: (view: any) => void; onDelete: (viewId: number) => void; onRename: (view: any) => void; onSetDefault: (viewId: number) => void; onImport: () => void; deletingId?: number; defaultingId?: number }) { const campaignName = (id: number) => campaigns.find(campaign => campaign.id === id)?.campaignName || campaigns.find(campaign => campaign.id === id)?.productName || "Unavailable campaign"; return <section className="mb-7 rounded-[22px] border border-white/[.07] bg-white/[.018] px-4 py-3"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><Bookmark className="h-3.5 w-3.5 text-rose-200" /><p className="text-[10px] font-bold uppercase tracking-[.16em] text-white/42">Saved comparison views</p></div><button type="button" onClick={onImport} className="inline-flex items-center gap-1.5 text-xs font-semibold text-rose-200 hover:text-rose-100"><FileUp className="h-3.5 w-3.5" />Import reporting CSV</button></div>{isError ? <div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200/15 bg-amber-100/[.035] px-3 py-2"><p className="text-xs text-amber-100/80">Saved views could not be loaded. Your active filters are unchanged.</p><button type="button" onClick={onRetry} className="text-xs font-semibold text-amber-100 hover:text-white">Retry</button></div> : views.length ? <div className="mt-3 flex flex-wrap gap-2">{views.map(view => <div key={view.id} className={`group flex max-w-full items-center gap-1 rounded-xl border px-1.5 py-1 ${view.isDefault ? "border-rose-200/30 bg-rose-200/[.06]" : "border-white/[.08] bg-[#171521]/80"}`}><button type="button" onClick={() => onApply(view)} className="min-w-0 rounded-lg px-2 py-1.5 text-left hover:bg-white/[.06]"><span className="flex items-center gap-1 truncate text-xs font-semibold text-white/80">{view.isDefault === 1 && <Pin className="h-3 w-3 shrink-0 text-rose-200" />}{view.name}</span><span className="block max-w-[240px] truncate text-[10px] text-white/38">{datePresetLabels[view.datePreset as DatePreset] || view.datePreset} · {view.campaignIds.length ? view.campaignIds.map(campaignName).join(" vs ") : "All campaigns"}</span></button><button type="button" onClick={() => onRename(view)} className="grid h-7 w-7 place-items-center rounded-lg text-white/30 hover:bg-white/[.06] hover:text-white" aria-label={`Rename ${view.name}`}><Pencil className="h-3.5 w-3.5" /></button><button type="button" onClick={() => onSetDefault(view.id)} disabled={view.isDefault === 1 || defaultingId === view.id} className="grid h-7 w-7 place-items-center rounded-lg text-white/30 hover:bg-rose-200/10 hover:text-rose-200 disabled:text-rose-200" aria-label={`Set ${view.name} as default`}><Pin className="h-3.5 w-3.5" /></button><button type="button" onClick={() => onDelete(view.id)} disabled={deletingId === view.id} className="grid h-7 w-7 place-items-center rounded-lg text-white/30 hover:bg-rose-200/10 hover:text-rose-200" aria-label={`Delete ${view.name}`}><Trash2 className="h-3.5 w-3.5" /></button></div>)}</div> : <p className="mt-2 text-xs text-white/35">Save an analysis window to return to this comparison instantly.</p>}</section>; }
function RenameViewDialog({ view, name, isSaving, onName, onClose, onSubmit }: { view: any; name: string; isSaving: boolean; onName: (value: string) => void; onClose: () => void; onSubmit: (event: React.FormEvent) => void }) { return <Dialog open={Boolean(view)} onOpenChange={open => { if (!open) onClose(); }}><DialogContent className="border-white/10 bg-[#191621] text-white sm:max-w-md"><form onSubmit={onSubmit}><DialogHeader><DialogTitle className="font-display text-3xl">Rename saved view</DialogTitle><DialogDescription className="leading-6 text-white/50">Update the label without changing this view’s stored campaign selection or reporting window.</DialogDescription></DialogHeader><div className="mt-5"><Label htmlFor="rename-view" className="text-xs text-white/65">View name</Label><Input id="rename-view" autoFocus value={name} onChange={event => onName(event.target.value)} className="mt-2 border-white/10 bg-white/[.04] text-white" /></div><DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={onClose} className="border-white/10 bg-transparent text-white hover:bg-white/[.08] hover:text-white">Cancel</Button><Button type="submit" disabled={isSaving} className="bg-rose-200 text-[#281b2d] hover:bg-rose-100">{isSaving ? "Saving…" : "Update name"}</Button></DialogFooter></form></DialogContent></Dialog>; }
function CsvImportDialogEnhanced({ open, campaigns, fallbackCampaignId, mappingPreset, preview, isImporting, onFallback, onPreset, onFile, onClose, onImport }: { open: boolean; campaigns: any[]; fallbackCampaignId: string; mappingPreset: CsvMappingPreset; preview: { rows: unknown[]; errors: string[]; resolvedPreset: CsvMappingPreset; detectedPreset: CsvMappingPreset | null } | null; isImporting: boolean; onFallback: (value: string) => void; onPreset: (value: CsvMappingPreset) => void; onFile: (file: File) => void; onClose: () => void; onImport: () => void }) { return <Dialog open={open} onOpenChange={isOpen => { if (!isOpen) onClose(); }}><DialogContent className="border-white/10 bg-[#191621] text-white sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-3xl">Import reporting CSV</DialogTitle><DialogDescription className="leading-6 text-white/50">Choose a source preset to map familiar Meta, TikTok, or YouTube export headers. Auto-detect stays transparent: PulseForge shows the matching rule before any verified snapshot is imported.</DialogDescription></DialogHeader><div className="mt-5 grid gap-4 sm:grid-cols-3"><Field label="Source mapping"><select value={mappingPreset} onChange={event => onPreset(event.target.value as CsvMappingPreset)} className="mt-2 h-10 w-full rounded-md border border-white/10 bg-[#201d2b] px-3 text-xs text-white outline-none focus:ring-2 focus:ring-rose-200/60">{(Object.keys(csvMappingPresets) as CsvMappingPreset[]).map(preset => <option key={preset} value={preset}>{csvMappingPresets[preset].label}</option>)}</select><p className="mt-1 text-[10px] leading-4 text-white/38">{csvMappingPresets[mappingPreset].description}</p></Field><Field label="Reporting file"><Input type="file" accept=".csv,text/csv" onChange={event => { const file = event.target.files?.[0]; if (file) onFile(file); }} className="mt-2 border-white/10 bg-white/[.04] text-white file:mr-2 file:rounded-md file:border-0 file:bg-rose-200 file:px-2 file:py-1 file:text-xs file:font-semibold file:text-[#281b2d]" /></Field><Field label="Fallback campaign"><select value={fallbackCampaignId} onChange={event => onFallback(event.target.value)} className="mt-2 h-10 w-full rounded-md border border-white/10 bg-[#201d2b] px-3 text-xs text-white outline-none focus:ring-2 focus:ring-rose-200/60"><option value="">Choose if CSV lacks campaign</option>{campaigns.map(campaign => <option key={campaign.id} value={campaign.id}>{campaign.campaignName || campaign.productName}</option>)}</select><p className="mt-1 text-[10px] leading-4 text-white/38">Only used when a campaign field is absent.</p></Field></div>{preview && <div className="mt-5 rounded-2xl border border-white/[.08] bg-white/[.025] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold">Import review</p><p className="mt-1 text-xs text-white/45">{preview.rows.length} valid snapshot{preview.rows.length === 1 ? "" : "s"} ready to import.</p></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.13em] ${preview.errors.length ? "bg-amber-200/10 text-amber-100" : "bg-emerald-300/10 text-emerald-200"}`}>{preview.errors.length ? `${preview.errors.length} issue${preview.errors.length === 1 ? "" : "s"}` : "Ready"}</span></div><div className="mt-4 flex flex-wrap gap-2 text-[10px] font-semibold uppercase tracking-[.11em]"><span className="rounded-full border border-rose-200/20 bg-rose-200/10 px-2.5 py-1 text-rose-100">Using {csvMappingPresets[preview.resolvedPreset].label}</span>{mappingPreset === "auto" && <span className="rounded-full border border-white/10 bg-white/[.03] px-2.5 py-1 text-white/45">{preview.detectedPreset ? `Detected ${csvMappingPresets[preview.detectedPreset].label}` : "No platform pattern detected"}</span>}</div>{preview.errors.length > 0 && <ul className="mt-4 space-y-1 text-xs leading-5 text-amber-100/85">{preview.errors.slice(0, 5).map(error => <li key={error}>• {error}</li>)}{preview.errors.length > 5 && <li>• And {preview.errors.length - 5} more issues.</li>}</ul>}<p className="mt-4 text-[11px] leading-5 text-white/38">The import is blocked until every reported row is valid. This prevents partial or misattributed performance data from entering your analysis.</p></div>}<DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={onClose} className="border-white/10 bg-transparent text-white hover:bg-white/[.08] hover:text-white">Cancel</Button><Button type="button" disabled={!preview?.rows.length || Boolean(preview?.errors.length) || isImporting} onClick={onImport} className="bg-rose-200 text-[#281b2d] hover:bg-rose-100">{isImporting ? "Importing…" : <><FileUp className="mr-2 h-4 w-4" />Import verified snapshots</>}</Button></DialogFooter></DialogContent></Dialog>; }
function CsvImportDialog({ open, campaigns, fallbackCampaignId, preview, isImporting, onFallback, onFile, onClose, onImport }: { open: boolean; campaigns: any[]; fallbackCampaignId: string; preview: { rows: unknown[]; errors: string[] } | null; isImporting: boolean; onFallback: (value: string) => void; onFile: (file: File) => void; onClose: () => void; onImport: () => void }) { return <Dialog open={open} onOpenChange={isOpen => { if (!isOpen) onClose(); }}><DialogContent className="border-white/10 bg-[#191621] text-white sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-3xl">Import reporting CSV</DialogTitle><DialogDescription className="leading-6 text-white/50">Bring reporting exports into PulseForge as verified snapshots.</DialogDescription></DialogHeader><DialogFooter className="mt-6"><Button type="button" variant="outline" onClick={onClose} className="border-white/10 bg-transparent text-white hover:bg-white/[.08] hover:text-white">Cancel</Button><Button type="button" disabled={!preview?.rows.length || Boolean(preview?.errors.length) || isImporting} onClick={onImport} className="bg-rose-200 text-[#281b2d] hover:bg-rose-100"><FileUp className="mr-2 h-4 w-4" />Import</Button></DialogFooter></DialogContent></Dialog>; }
function SavedViews({ views, campaigns, isError, onRetry, onApply, onDelete, deletingId }: { views: any[]; campaigns: any[]; isError: boolean; onRetry: () => void; onApply: (view: any) => void; onDelete: (viewId: number) => void; deletingId?: number }) { const campaignName = (id: number) => campaigns.find(campaign => campaign.id === id)?.campaignName || campaigns.find(campaign => campaign.id === id)?.productName || "Unavailable campaign"; return <section className="mb-7 rounded-[22px] border border-white/[.07] bg-white/[.018] px-4 py-3"><div className="flex items-center gap-2"><Bookmark className="h-3.5 w-3.5 text-rose-200" /><p className="text-[10px] font-bold uppercase tracking-[.16em] text-white/42">Saved comparison views</p></div>{isError ? <div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200/15 bg-amber-100/[.035] px-3 py-2"><p className="text-xs text-amber-100/80">Saved views could not be loaded. Your active filters are unchanged.</p><button type="button" onClick={onRetry} className="text-xs font-semibold text-amber-100 hover:text-white">Retry</button></div> : views.length ? <div className="mt-3 flex flex-wrap gap-2">{views.map(view => <div key={view.id} className="group flex max-w-full items-center gap-1 rounded-xl border border-white/[.08] bg-[#171521]/80 px-1.5 py-1"><button type="button" onClick={() => onApply(view)} className="min-w-0 rounded-lg px-2 py-1.5 text-left hover:bg-white/[.06]"><span className="block truncate text-xs font-semibold text-white/80">{view.name}</span><span className="block max-w-[240px] truncate text-[10px] text-white/38">{datePresetLabels[view.datePreset as DatePreset] || view.datePreset} · {view.campaignIds.length ? view.campaignIds.map(campaignName).join(" vs ") : "All campaigns"}</span></button><button type="button" onClick={() => onDelete(view.id)} disabled={deletingId === view.id} className="grid h-7 w-7 place-items-center rounded-lg text-white/30 hover:bg-rose-200/10 hover:text-rose-200" aria-label={`Delete ${view.name}`}><Trash2 className="h-3.5 w-3.5" /></button></div>)}</div> : <p className="mt-2 text-xs text-white/35">Save an analysis window to return to this comparison instantly.</p>}</section>; }
function InvalidDateRangeState() { return <section className="grid min-h-[360px] place-items-center rounded-[28px] border border-amber-200/20 bg-amber-100/[.035] p-8 text-center"><div><span className="mx-auto grid h-11 w-11 place-items-center rounded-2xl bg-amber-200/10 text-amber-100"><CalendarRange className="h-5 w-5" /></span><h3 className="mt-5 font-display text-3xl">Correct the analysis window to continue.</h3><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-white/50">The end date must be on or after the start date. Your previously stored metrics are unaffected.</p></div></section>; }

function AnalyticsError({ onRetry }: { onRetry: () => void }) { return <section className="grid min-h-[430px] place-items-center rounded-[30px] border border-amber-200/20 bg-amber-100/[.035] p-8 text-center"><div><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-amber-200/10 text-amber-100"><AlertTriangle className="h-5 w-5" /></span><p className="mt-6 text-[10px] font-bold uppercase tracking-[.18em] text-amber-100/75">Signal unavailable</p><h3 className="mt-3 font-display text-4xl">The performance feed could not be loaded.</h3><p className="mx-auto mt-4 max-w-md text-sm leading-7 text-white/50">Your saved campaign data is unchanged. Check the connection and try loading the verified snapshots again.</p><Button onClick={onRetry} variant="outline" className="mt-7 border-white/10 bg-white/[.04] text-white hover:bg-white/10 hover:text-white"><RefreshCw className="mr-2 h-4 w-4" />Retry analytics</Button></div></section>; }

function EmptyAnalytics({ onAdd, hasCampaigns }: { onAdd: () => void; hasCampaigns: boolean }) { return <section className="relative overflow-hidden rounded-[30px] border border-white/[.09] bg-[#171521]/88 p-7 shadow-2xl shadow-black/10"><div className="absolute -right-24 -top-28 h-72 w-72 rounded-full bg-rose-300/10 blur-3xl" /><div className="relative grid min-h-[430px] gap-10 xl:grid-cols-[.82fr_1.18fr] xl:items-center"><div className="text-left"><span className="grid h-12 w-12 place-items-center rounded-2xl border border-rose-200/20 bg-rose-200/10 text-rose-200"><ChartNoAxesCombined className="h-5 w-5" /></span><p className="mt-7 text-[10px] font-bold uppercase tracking-[.18em] text-rose-200/70">Signal calibration</p><h3 className="mt-3 max-w-md font-display text-4xl leading-[1.05]">Your analytics view begins with a verified signal.</h3><p className="mt-4 max-w-md text-sm leading-7 text-white/52">{hasCampaigns ? "Add a first snapshot from your platform reporting to unlock trends, channel contribution, and campaign-level performance." : "Generate a campaign first, then add platform metrics from its live reporting source."}</p><Button onClick={onAdd} disabled={!hasCampaigns} className="mt-7 bg-white text-[#261d2d] hover:bg-rose-50"><Plus className="mr-2 h-4 w-4" />Add verified metrics</Button></div><div className="rounded-[24px] border border-white/[.08] bg-[#0e0d16]/60 p-5"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold">Signal scaffold</p><p className="mt-1 text-[11px] text-white/38">Waiting for first-party platform snapshots</p></div><span className="rounded-full border border-white/10 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.12em] text-white/38">Uncalibrated</span></div><div className="relative mt-6 h-44 overflow-hidden rounded-2xl border border-white/[.06] bg-[linear-gradient(rgba(255,255,255,.025)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,.025)_1px,transparent_1px)] bg-[size:24px_24px]"><svg viewBox="0 0 600 176" className="absolute inset-0 h-full w-full" aria-hidden="true"><path d="M0 112 C65 112 74 97 119 101 S184 76 230 93 S298 137 343 112 S420 91 473 104 S548 77 600 90" fill="none" stroke="rgba(245,200,218,.22)" strokeWidth="2" strokeDasharray="5 8" /><path d="M0 134 C68 134 102 125 146 130 S247 115 297 125 S379 146 430 130 S519 107 600 123" fill="none" stroke="rgba(165,140,255,.15)" strokeWidth="2" strokeDasharray="4 10" /></svg><div className="absolute bottom-3 left-4 right-4 flex justify-between text-[9px] font-bold uppercase tracking-[.16em] text-white/25"><span>Capture</span><span>Verify</span><span>Compare</span><span>Act</span></div></div><div className="mt-4 grid grid-cols-3 gap-3">{(["Meta", "TikTok", "YouTube"] as const).map((platform, index) => <div key={platform} className="rounded-xl border border-white/[.06] bg-white/[.02] px-3 py-3"><span className="block h-1.5 w-8 rounded-full" style={{ backgroundColor: ["#8b9cff", "#ef80aa", "#f0bf6b"][index], opacity: .45 }} /><p className="mt-3 text-xs font-semibold text-white/55">{platform}</p><p className="mt-1 text-[10px] text-white/28">Awaiting data</p></div>)}</div></div></div></section>; }

function AnalyticsView({ data, platformChartData, comparisonIds, rangeLabel }: { data: any; platformChartData: any[]; comparisonIds: number[]; rangeLabel: string }) { const interpretation = getPerformanceInterpretation(data.platforms); return <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><MetricCard icon={Eye} label="Impressions" value={formatNumber(data.totals.impressions)} note={`${data.snapshotCount} verified snapshots`} /><MetricCard icon={Activity} label="Engagement rate" value={`${data.totals.engagementRate}%`} note={`${formatNumber(data.totals.engagements)} engagements`} /><MetricCard icon={MousePointerClick} label="Click-through rate" value={`${data.totals.clickThroughRate}%`} note={`${formatNumber(data.totals.clicks)} clicks`} /><MetricCard icon={Target} label="Conversions" value={formatNumber(data.totals.conversions)} note={`${data.totals.conversionRate}% click-to-convert`} /><MetricCard icon={CircleDollarSign} label="Cost / conversion" value={formatMoney(data.totals.costPerConversion)} note={`${formatMoney(data.totals.spend)} verified spend`} /></section>
  <section className="mt-5 grid gap-5 xl:grid-cols-[1.32fr_.68fr]"><Panel eyebrow="Trend line" title="Demand and interaction over time"><ChartContainer config={trendConfig} className="mt-6 h-[280px] w-full"><AreaChart data={data.timeline} margin={{ left: 8, right: 8, top: 8 }}><defs><linearGradient id="impressionsFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-impressions)" stopOpacity={0.38} /><stop offset="100%" stopColor="var(--color-impressions)" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(255,255,255,.08)" /><XAxis dataKey="date" tickLine={false} axisLine={false} tickMargin={10} /><YAxis hide /><ChartTooltip content={<ChartTooltipContent indicator="line" />} /><Area type="monotone" dataKey="impressions" stroke="var(--color-impressions)" strokeWidth={2.5} fill="url(#impressionsFill)" /><Area type="monotone" dataKey="engagements" stroke="var(--color-engagements)" strokeWidth={2.5} fill="transparent" /></AreaChart></ChartContainer></Panel><Panel eyebrow="Platform mix" title="Where reach is landing"><ChartContainer config={platformConfig} className="mt-6 h-[280px] w-full"><BarChart data={platformChartData} layout="vertical" margin={{ left: 0, right: 14 }}><CartesianGrid horizontal={false} stroke="rgba(255,255,255,.08)" /><XAxis type="number" hide /><YAxis dataKey="name" type="category" tickLine={false} axisLine={false} width={58} /><ChartTooltip content={<ChartTooltipContent hideLabel />} /><Bar dataKey="impressions" radius={[0, 8, 8, 0]} /></BarChart></ChartContainer></Panel></section>
  <section className="mt-5 grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Panel eyebrow="Channel efficiency" title="Platform performance"><div className="mt-5 space-y-3">{data.platforms.map((item: any) => <div key={item.platform} className="rounded-2xl border border-white/[.07] bg-white/[.025] p-4"><div className="flex items-start justify-between"><div><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ backgroundColor: platformTone[item.platform as Platform] }} /><p className="text-sm font-semibold">{platformNames[item.platform as Platform]}</p></div><p className="mt-1 text-xs text-white/42">{formatNumber(item.impressions)} impressions · {item.engagementRate}% engagement</p></div><p className="text-sm font-semibold text-rose-100">{item.clickThroughRate}% CTR</p></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className="h-full rounded-full" style={{ width: `${Math.min(100, item.engagementRate * 10)}%`, backgroundColor: platformTone[item.platform as Platform] }} /></div></div>)}</div></Panel><Panel eyebrow="Campaign signals" title="Performance by campaign"><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[540px] text-left"><thead className="text-[10px] font-bold uppercase tracking-[.14em] text-white/35"><tr><th className="pb-3">Campaign</th><th className="pb-3 text-right">Impressions</th><th className="pb-3 text-right">Engagement</th><th className="pb-3 text-right">CTR</th><th className="pb-3 text-right">Conversions</th></tr></thead><tbody>{data.campaigns.map((item: any) => <tr key={item.campaignId} className="border-t border-white/[.07] text-sm"><td className="py-4 font-medium">{item.campaignName}</td><td className="py-4 text-right text-white/63">{formatNumber(item.impressions)}</td><td className="py-4 text-right text-white/63">{item.engagementRate}%</td><td className="py-4 text-right text-white/63">{item.clickThroughRate}%</td><td className="py-4 text-right font-semibold text-rose-100">{formatNumber(item.conversions)}</td></tr>)}</tbody></table></div></Panel></section>
  {comparisonIds.length === 2 && <CampaignComparison campaignIds={comparisonIds} campaigns={data.campaigns} rangeLabel={rangeLabel} />}
  {interpretation.length > 0 && <section className="mt-5 rounded-[26px] border border-rose-200/15 bg-gradient-to-br from-rose-300/[.08] via-[#171521]/90 to-violet-300/[.08] p-6 shadow-2xl shadow-black/10"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-rose-200/12 text-rose-200"><BrainCircuit className="h-5 w-5" /></span><div><p className="text-sm font-semibold">Performance interpretation</p><p className="mt-1 max-w-xl text-xs leading-5 text-white/48">A transparent read of the verified numbers above. These cues use no assumed benchmarks or external claims.</p></div></div><span className="rounded-full border border-white/[.08] bg-white/[.03] px-3 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-white/40">Evidence-led</span></div><div className="mt-6 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{interpretation.map((cue, index) => <div key={cue.eyebrow} className="rounded-2xl border border-white/[.08] bg-black/15 p-4"><div className="flex items-center justify-between"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-rose-100/65">{cue.eyebrow}</p><ArrowUpRight className="h-3.5 w-3.5 text-white/35" /></div><p className="mt-5 text-sm font-semibold leading-5">{cue.title}</p><p className="mt-2 text-xs leading-5 text-white/50">{cue.detail}</p></div>)}</div></section>}
  <section className="mt-5 rounded-[26px] border border-white/[.09] bg-[#171521]/88 p-6"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-200"><Video className="h-5 w-5" /></span><div><p className="text-sm font-semibold">Engagement lens</p><p className="mt-1 text-sm leading-6 text-white/50">{formatNumber(data.totals.videoViews)} video views and {formatNumber(data.totals.saves)} saves are recorded across all verified snapshots. Use this alongside click-through and conversion rates to determine which creative messages are earning attention versus action.</p></div></div></section></>; }

function MetricCard({ icon: Icon, label, value, note }: { icon: any; label: string; value: string; note: string }) { return <div className="rounded-2xl border border-white/[.09] bg-[#171521]/88 p-5"><div className="flex items-center justify-between"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-white/40">{label}</p><Icon className="h-4 w-4 text-rose-200" /></div><p className="mt-5 font-display text-3xl">{value}</p><p className="mt-2 text-xs text-white/45">{note}</p></div>; }
function Panel({ eyebrow, title, children }: { eyebrow: string; title: string; children: React.ReactNode }) { return <section className="rounded-[26px] border border-white/[.09] bg-[#171521]/88 p-6 shadow-2xl shadow-black/10"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-rose-200/65">{eyebrow}</p><h3 className="mt-2 font-display text-2xl">{title}</h3>{children}</section>; }
function CampaignComparison({ campaignIds, campaigns, rangeLabel }: { campaignIds: number[]; campaigns: any[]; rangeLabel: string }) { const compared = campaignIds.map(id => campaigns.find((campaign: any) => campaign.campaignId === id)).filter(Boolean); if (compared.length < 2) return <section className="mt-5 rounded-[26px] border border-violet-300/15 bg-violet-300/[.05] p-6"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/12 text-violet-200"><GitCompareArrows className="h-5 w-5" /></span><div><p className="text-sm font-semibold">Campaign comparison is waiting for both signals.</p><p className="mt-1 text-sm leading-6 text-white/50">One of the selected campaigns has no verified snapshots in the current analysis window. Adjust the date range or record a metric snapshot to compare both campaigns.</p></div></div></section>; const [first, second] = compared; const ctrGap = Number((first.clickThroughRate - second.clickThroughRate).toFixed(2)); const engagementGap = Number((first.engagementRate - second.engagementRate).toFixed(2)); return <section className="mt-5 rounded-[26px] border border-violet-300/18 bg-gradient-to-br from-violet-300/[.10] via-[#171521]/90 to-rose-300/[.06] p-6 shadow-2xl shadow-black/10"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-300/15 text-violet-200"><GitCompareArrows className="h-5 w-5" /></span><div><p className="text-sm font-semibold">Campaign comparison</p><p className="mt-1 text-xs text-white/48">Side-by-side view for {rangeLabel}. All differences use only the selected campaigns’ verified snapshots.</p></div></div><span className="rounded-full border border-white/[.08] bg-white/[.03] px-3 py-1 text-[10px] font-bold uppercase tracking-[.14em] text-white/40">2 campaigns</span></div><div className="mt-6 grid gap-3 lg:grid-cols-2">{[first, second].map((campaign: any, index: number) => <div key={campaign.campaignId} className="rounded-2xl border border-white/[.08] bg-black/15 p-5"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-violet-200/70">Campaign {index + 1}</p><p className="mt-3 font-display text-2xl">{campaign.campaignName}</p><div className="mt-5 grid grid-cols-2 gap-3"><CompareMetric label="Impressions" value={formatNumber(campaign.impressions)} /><CompareMetric label="Engagement" value={`${campaign.engagementRate}%`} /><CompareMetric label="CTR" value={`${campaign.clickThroughRate}%`} /><CompareMetric label="Conversions" value={formatNumber(campaign.conversions)} /></div></div>)}</div><p className="mt-5 text-xs leading-5 text-white/50">CTR difference: <span className="font-semibold text-rose-100">{Math.abs(ctrGap).toFixed(2)} points</span>. Engagement-rate difference: <span className="font-semibold text-rose-100">{Math.abs(engagementGap).toFixed(2)} points</span>. Use the creative and audience inputs behind the higher signal as the next review point.</p></section>; }
function CompareMetric({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-white/[.06] bg-white/[.025] px-3 py-3"><p className="text-[9px] font-bold uppercase tracking-[.13em] text-white/35">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>; }
